function restoreArchiveFile(file){return new Promise(function(resolve){if(!file){resolve({ok:false,cancelled:true});return}var r=new FileReader();r.onerror=function(){resolve({ok:false,message:'خواندن فایل انجام نشد.'})};r.onload=async function(){var text=String(r.result||''),first=await restoreArchiveText(text,null);if(!first.needPassphrase){resolve(first);return}var pass=prompt(first.prompt||'رمز پشتیبان این آرشیو را وارد کن:','');if(pass===null){resolve({ok:false,cancelled:true,message:'بازیابی لغو شد.'});return}resolve(await restoreArchiveText(text,String(pass)))};r.readAsText(file)})}
