function directArchiveRowsHtml(){var rows=readArchiveCatalog().filter(function(x){return x&&x.archiveId&&x.archiveFileFormat===ARCHIVE_FILE_FORMAT}).slice(-6).reverse();if(!rows.length)return '<div class="arlt-empty">هنوز آرشیو جدیدی برای بازیابی مستقیم روی همین گوشی ثبت نشده است.</div>';return rows.map(function(x){var done=String(x.restoredAt||'');return '<div class="arlt-customer arlt-direct-row"><div class="arlt-direct-info"><b>'+esc(x.customerName||'مشتری')+'</b><small>'+esc(x.filename||'')+'<br>'+(done?'بازیابی‌شده':'آماده بازیابی مستقیم')+'</small></div><div class="arlt-direct-actions"><button class="btn '+(done?'ghost':'green')+' small" data-arlt-action="restoreLocal" data-archive-id="'+esc(x.archiveId)+'">'+(done?'بررسی وضعیت':'بازیابی مستقیم')+'</button><button class="btn red small arlt-direct-delete" data-arlt-action="archiveListDelete" data-archive-id="'+esc(x.archiveId)+'">حذف</button></div></div>'}).join('')}
