function backupCards(){var s=window.AlanRangLongTerm&&window.AlanRangLongTerm.backupSummary?window.AlanRangLongTerm.backupSummary():{count:0,rows:[]},last=s.latest;return '<div class="arlt-kpis"><div><span>نسخه‌های تأییدشده</span><b>'+fa(s.count||0)+'</b></div><div><span>حد نگهداری</span><b>'+fa(s.maxGenerations||10)+'</b></div></div>'+(last?'<p class="arlt-small">آخرین: '+esc(last.filename)+'<br>SHA-256: <code>'+esc(String(last.sha256||'').slice(0,16))+'…</code></p>':'<p class="arlt-small">هنوز پشتیبان چندنسلی ساخته نشده است.</p>')}
