function pageHtml(){var m=window.AlanRangLongTerm&&window.AlanRangLongTerm.migrationStatus?window.AlanRangLongTerm.migrationStatus():{},sign=window.AlanRangLongTerm&&window.AlanRangLongTerm.signingStatus?window.AlanRangLongTerm.signingStatus():{},gate=window.AlanRangLongTerm&&window.AlanRangLongTerm.releaseSafetyStatus?window.AlanRangLongTerm.releaseSafetyStatus():{},scan=state&&state.arltLastIntegrity||null;return '<section class="page arlt-page"><div class="back-row"><button class="btn ghost" data-action="tab" data-tab="home">برگشت به خانه</button></div><div class="arlt-hero"><h2>🛡️ حفاظت بلندمدت اطلاعات</h2><p>این مرکز برای نگهداری چندساله آلان‌رنگ طراحی شده است. هیچ عملیات پاک‌سازی بدون پشتیبان تأییدشده و تأیید دوم انجام نمی‌شود.</p></div><div class="card"><h3>۱) پشتیبان چندنسلی و تأیید Read-back</h3>'+backupCards()+'<button class="btn gold full" data-arlt-action="backup">ساخت پشتیبان تأییدشده</button></div><div class="card"><h3>۲) نسخه مستقل از گوشی</h3><p class="arlt-small">یک پشتیبان تازه و سالم ساخته می‌شود، سپس پنجره اشتراک‌گذاری باز می‌شود تا آن را روی لپ‌تاپ، فلش OTG یا فضای امن دیگری ذخیره کنی.</p><button class="btn blue full" data-arlt-action="offdevice">ساخت و ارسال نسخه خارج از گوشی</button></div><div class="card"><h3>۳) بسته نجات اضطراری</h3><p class="arlt-small">یک پشتیبان رمزگذاری‌شده تازه + Manifest نجات می‌سازد. APK/SOURCE دقیق همین Release در بسته نجات همراه نسخه تحویلی نگهداری می‌شود؛ رمز و کلید خصوصی داخل آن نیست.</p><button class="btn blue full" data-arlt-action="recovery">ساخت Emergency Recovery Package</button></div><div class="card"><h3>۴) دفتر مهاجرت ساختار داده</h3><div class="arlt-row"><span>Schema فعال</span><b>'+fa(m.currentSchema||0)+'</b></div><div class="arlt-row"><span>اجرای ناموفق/ناتمام</span><b>'+fa((m.failed||0)+(m.incomplete||0))+'</b></div>'+statusBadge(!(m.failed||m.incomplete),'Ledger سالم','نیاز به بررسی')+'</div><div class="card"><h3>۵) ممیزی عمیق فقط‌خواندنی</h3>'+(scan?'<div class="arlt-kpis"><div><span>بحرانی</span><b>'+fa(scan.summary.critical)+'</b></div><div><span>هشدار</span><b>'+fa(scan.summary.warnings)+'</b></div></div>':'<p class="arlt-small">برای بررسی ارتباط حساب‌ها، چک‌ها، اسناد، Schema، Archive Checkpoint و حجم داده اسکن را اجرا کن.</p>')+'<button class="btn ghost full" data-arlt-action="integrity">اجرای اسکن عمیق</button></div><div class="card"><h3>۶) خروجی قابل‌خواندن مستقل از برنامه</h3><p class="arlt-small">CSV و JSON برای دسترسی آینده. فایل‌های CSV/JSON رمزگذاری نشده‌اند و باید در محل امن نگهداری شوند.</p><button class="btn ghost full" data-arlt-action="portable">ساخت خروجی CSV/JSON</button></div><div class="card"><h3>۷) تداوم امضای رسمی</h3><div class="arlt-row"><span>Package</span><b>'+esc(sign.package||'—')+'</b></div><div class="arlt-row"><span>گواهی رسمی Release</span><b>ثبت‌شده</b></div>'+statusBadge(!!sign.ok,'هویت Release سالم','هویت نسخه نیاز به بررسی دارد')+'<button class="btn ghost full arlt-mt" data-arlt-action="signing">بررسی دوباره امضا</button></div><div class="card"><h3>۸) Release Safety Gate</h3><p class="arlt-small">Update مستقیم، ممنوعیت Clear Data، عدم وجود کلید خصوصی در Source و قفل نهایی فقط پس از تست واقعی گوشی.</p>'+statusBadge(!!gate.ok,'Runtime Gate سالم','Runtime Gate کامل نیست')+'</div><div class="card arlt-danger"><h3>۹) آرشیو پایان سال و سبک‌سازی امن</h3><p class="arlt-small">فقط مشتری کاملاً تسویه‌شده. ابتدا پشتیبان کامل و فایل آرشیو رمزگذاری‌شده ساخته و Read-back می‌شوند؛ سپس با تأیید دوم سابقه سنگین از دیتای فعال خارج می‌شود. آرشیوهای جدید روی همین نصب با کلید امن دستگاه بدون ورود رمز بازیابی می‌شوند؛ انتقال به گوشی دیگر همچنان به رمز پشتیبان نیاز دارد. آرشیوهای ساخته‌شده قبل از FIX1 برای بازیابی به رمز قبلی نیاز دارند.</p>'+archiveListHtml()+'<hr><h4>بازیابی مستقیم روی همین گوشی</h4>'+directArchiveRowsHtml()+'<button class="btn ghost full arlt-mt" data-arlt-action="restoreChoose">انتخاب فایل از حافظه / آرشیو قدیمی</button><input id="arltArchiveFile" type="file" accept=".alr,.txt,application/json" style="display:none"><p class="arlt-small">برای آرشیوهای جدید ابتدا «بازیابی مستقیم» را بزن؛ این مسیر از فایل‌چوزر Android خارج نمی‌شود و برای تکرار تست پایدارتر است. انتخاب فایل فقط برای آرشیو قدیمی یا انتقال از گوشی دیگر است. بازیابی خودکار فقط زمانی مجاز است که بعد از آرشیو برای آن مشتری فعالیت جدیدی ثبت نشده باشد. دکمه «حذف» فقط همان ردیف را از فهرست مستقیم و Cache داخلی کنار می‌گذارد؛ فایل اصلی .alr و کلید امن بازیابی حذف نمی‌شوند.</p></div><div class="card"><h3>۱۰) سطل زباله امن ۹۰ روزه</h3><p class="arlt-small">حذف‌های امن برنامه تا ۹۰ روز در Recycle Bin نگهداری می‌شوند و قبل از پایان این دوره پاک‌سازی دائمی نمی‌شوند. این داده‌ها داخل پشتیبان کامل نیز حضور دارند.</p><button class="btn ghost full" data-action="tab" data-tab="trash">باز کردن سطل زباله</button></div></section>'}
